{-# LANGUAGE OverloadedStrings #-}

module Main where

import Web.Scotty
import qualified Data.Text.Lazy as TL
import qualified Data.ByteString.Lazy as BL
import Data.Csv
import qualified Data.Vector as V
import Data.List (nub)
import System.Directory (doesFileExist)
import GHC.Generics

-- --------------------------------------------
-- DATA MODEL
-- --------------------------------------------

data Waste = Waste
  { country  :: !String
  , measure  :: !String
  , year     :: !Int
  , wasteVal :: !Int
  } deriving (Show)

instance FromNamedRecord Waste where
  parseNamedRecord r =
    Waste <$> r .: "Country"
          <*> r .: "Measure"
          <*> r .: "Year"
          <*> r .: "WasteValue"

-- --------------------------------------------
-- CSV LOADING  (optional — data is embedded)
-- --------------------------------------------

loadWasteData :: IO (Either String [Waste])
loadWasteData = do
  let path = "data/waste26.csv"
  exists <- doesFileExist path
  if not exists
    then return (Left "CSV not found (not required — data is embedded in HTML)")
    else do
      raw <- BL.readFile path
      case decodeByName raw of
        Left err     -> return (Left err)
        Right (_, v) -> return (Right (V.toList v))

uniqueCountries :: [Waste] -> [String]
uniqueCountries = nub . map country

