lns=\"http://www.w3.org/2000/svg\" width=\"32\" height=\"32\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\" stroke-width=\"1.5\"><path d=\"M21 8l-9-5-9 5v8l9 5 9-5V8z\"/><path d=\"M3.27 6.96L12 12.01l8.73-5.05M12 22.08V12\"/></svg>`,val:fmt(gs.globalTotal),label:'Total Recorded (tonnes)',c:'var(--accent4)'},\n    {icon:`<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"32\" height=\"32\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\" stroke-width=\"1.5\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"18\" rx=\"2\"/><path d=\"M16 2v4M8 2v4M3 10h18\"/></svg>`,val:gs.yearMin+'–'+gs.yearMax,label:'Year Range',c:'var(--accent)'},\n    {icon:`<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"32\" height=\"32\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\" stroke-width=\"1.5\"><circle cx=\"12\" cy=\"15\" r=\"6\"/><path d=\"M8.21 13.89L7 23l5-3 5 3-1.21-9.12\"/><path d=\"M15 7H9l-2-5h10l-2 5z\"/></svg>`,val:gs.maxCountry,label:'Highest Single Record',c:'var(--accent3)'},\n    {icon:`<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"32\" height=\"32\" fill=\"none\" viewBox=\"0 0 24 24\" stroke=\"currentColor\" stroke-width=\"1.5\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\"/><path d=\"M8 17V13M12 17V8M16 17V11\"/></svg>`,val:gs.totalRecords.toLocaleString(),label:'Data Points',c:'var(--muted)'},\n  ];\n  document.getElementById('globalStatsRow').innerHTML=stats.map(s=>`<div class=\"g-stat\"><div class=\"g-stat-icon\">${s.icon}</div><div class=\"g-stat-val\" style=\"color:${s.c}\">${s.val}</div><div class=\"g-stat-label\">${s.label}</div></div>`).join('');\n\n  const yt=gs.yearlyTrend;\n  const gCtx=document.getElementById('globalChart').getContext('2d');\n  if(window._gC) window._gC.destroy();\n  const gGrad=gCtx.createLinearGradient(0,0,0,340);\n  gGrad.addColorStop(0,'rgba(124,58,237,.3)');gGrad.addColorStop(1,'rgba(124,58,237,0)');\n  window._gC=new Chart(gCtx,{type:'bar',data:{datasets:[{label:'Global Total Recycling (tonnes)',data:yt.map(p=>({x:p.year,y:p.value})),backgroundColor:gGrad,borderColor:'#7c3aed',borderWidth:1.5,borderRadius:4}]},options:{responsive:true,animation:{duration:900},plugins:{legend:{labels:{color:'#64748b'}},tooltip:{backgroundColor:'#ffffff',titleColor:'#1e293b',bodyColor:'#7c3aed',borderColor:'#e2e8f0',borderWidth:1,callbacks:{title:i=>'Year: '+i[0].parsed.x,label:i=>' '+i[0].parsed.y.toLocaleString()+' tonnes'}}},scales:{x:{type:'linear',ticks:{color:'#64748b'},grid:{color:'rgba(226,232,240,.9)'}},y:{ticks:{color:'#64748b',callback:v=>fmt(v)},grid:{color:'rgba(226,232,240,.9)'}}}}});\n\n  const top5=gs.top5;\n  const medals=['🥇','🥈','🥉','4️⃣','5️⃣'];\n  document.getElementById('top5Grid').innerHTML=top5.map((c,i)=>{const s=SUMMARY[c]||{};return `<div class=\"top5-card\" onclick=\"openDetail('${c.replace(/'/g,\"&#39;\")}','home')\"><div class=\"top5-rank\">${medals[i]}</div><div><div class=\"top5-flag\">${FLAGS[c]||'🌐'}</div><div class=\"top5-name\">${c}</div><div class=\"top5-val\">${fmt(s.latest||0)} tonnes (${s.latestYear||''})</div></div></div>`;}).join('');\n\n  const cAvg={},cCnt={};\n  COUNTRIES.forEach(c=>{const r=CONTINENTS[c]||'Other';const s=SUMMARY[c]||{};cAvg[r]=(cAvg[r]||0)+(s.avg||0);cCnt[r]=(cCnt[r]||0)+1;});\n  const regions=Object.keys(cAvg).sort();\n  const avgs=regions.map(r=>Math.round(cAvg[r]/cCnt[r]));\n  const cCtx=document.getElementById('continentChart').getContext('2d');\n  if(window._cC) window._cC.destroy();\n  window._cC=new Chart(cCtx,{type:'bar',data:{labels:regions,datasets:[{label:'Avg Recycling (tonnes)',data:avgs,backgroundColor:['#2563eb','#7c3aed','#db2777','#d97706','#0ea5e9','#ff69b4','#aef'],borderRadius:5}]},options:{indexAxis:'y',responsive:true,animation:{duration:900},plugins:{legend:{labels:{color:'#64748b'}},tooltip:{backgroundColor:'#ffffff',titleColor:'#1e293b',bodyColor:'#2563eb',borderColor:'#e2e8f0',borderWidth:1,callbacks:{label:i=>' '+i.parsed.x.toLocaleString()+' tonnes avg'}}},scales:{x:{ticks:{color:'#64748b',callback:v=>fmt(v)},grid:{color:'rgba(226,232,240,.9)'}},y:{ticks:{color:'#64748b'},grid:{color:'rgba(226,232,240,.9)'}}}}});\n  // Pie chart — continent share\n  const contShare={};\n  COUNTRIES.forEach(c=>{\n    const r=CONTINENTS[c]||'Other';\n    if(r==='Global') return;\n    const s=SUMMARY[c]||{};\n    contShare[r]=(contShare[r]||0)+(s.latest||0);\n  });\n  const pieLabels=Object.keys(contShare);\n  const pieVals=pieLabels.map(k=>contShare[k]);\n  const pieColors=['#2563eb','#7c3aed','#db2777','#d97706','#0ea5e9','#8b5cf6','#10b981'];\n  const pieCtx=document.getElementById('pieChart').getContext('2d');\n  if(window._pieC) window._pieC.destroy();\n  window._pieC=new Chart(pieCtx,{type:'doughnut',data:{labels:pieLabels,datasets:[{data:pieVals,backgroundColor:pieColors,borderColor:'#f5f7fa',borderWidth:3,hoverOffset:12}]},options:{responsive:true,animation:{duration:900},plugins:{legend:{position:'right',labels:{color:'#1e293b',font:{size:13},padding:14}},tooltip:{backgroundColor:'#ffffff',titleColor:'#1e293b',bodyColor:'#2563eb',borderColor:'#e2e8f0',borderWidth:1,callbacks:{label:i=>' '+i.label+': '+fmt(i.parsed)+' t'}}}}});\n\n  // Top-10 bar chart\n  const realCountries=COUNTRIES.filter(c=>!c.startsWith('OECD')&&c!=='European Union (27 countries from 01/02/2020)');\n  const top10=realCountries.slice().sort((a,b)=>(SUMMARY[b]?.latest||0)-(SUMMARY[a]?.latest||0)).slice(0,10);\n  const t10Labels=top10.map(c=>FLAGS[c]+' '+c);\n  const t10Vals=top10.map(c=>SUMMARY[c]?.latest||0);\n  const barGrad=document.getElementById('top10BarChart').getContext('2d').createLinearGradient(0,0,700,0);\n  barGrad.addColorStop(0,'#2563eb');barGrad.addColorStop(1,'#7c3aed');\n  const t10Ctx=document.getElementById('top10BarChart').getContext('2d');\n  if(window._t10C) window._t10C.destroy();\n  window._t10C=new Chart(t10Ctx,{type:'bar',data:{labels:t10Labels,datasets:[{label:'Latest Recycling (tonnes)',data:t10Vals,backgroundColor:barGrad,borderRadius:6,borderSkipped:false}]},options:{responsive:true,animation:{duration:900},plugins:{legend:{labels:{color:'#64748b'}},tooltip:{backgroundColor:'#ffffff',titleColor:'#1e293b',bodyColor:'#2563eb',borderColor:'#e2e8f0',borderWidth:1,callbacks:{label:i=>' '+i.parsed.y.toLocaleString()+' tonnes'}}},scales:{x:{ticks:{color:'#64748b',maxRotation:30},grid:{color:'rgba(226,232,240,.9)'}},y:{ticks:{color:'#64748b',callback:v=>fmt(v)},grid:{color:'rgba(226,232,240,.9)'}}}}});\n\n}\n\nlet curFilter='',curSort='name',curRegion='';\nfunction filterCards(){curFilter=document.getElementById('search').value.toLowerCase();renderCards();}\nfunction renderCards(){\n  curSort=document.getElementById('sortBy').value;\n  curRegion=document.getElementById('continentFilter').value;\n  let list=COUNTRIES.filter(c=>c.toLowerCase().includes(curFilter)&&(!curRegion||(CONTINENTS[c]||'')==curRegion));\n  if(curSort==='latest') list.sort((a,b)=>(SUMMARY[b]?.latest||0)-(SUMMARY[a]?.latest||0));\n  else if(curSort==='growth') list.sort((a,b)=>(SUMMARY[b]?.growth||0)-(SUMMARY[a]?.growth||0));\n  else if(curSort==='avg') list.sort((a,b)=>(SUMMARY[b]?.avg||0)-(SUMMARY[a]?.avg||0));\n  else list.sort();\n  const grid=document.getElementById('overviewGrid');\n  if(!list.length){grid.innerHTML=\"<div class='no-results'>No countries found</div>\";return;}\n  grid.innerHTML=list.map((c,i)=>{const s=SUMMARY[c]||{};const region=CONTINENTS[c]||'';return `<div class=\"card\" style=\"animation:fadeIn .3s ease ${(i%12)*32}ms both\" onclick=\"openDetail('${c.replace(/'/g,\"&#39;\")}','countries')\"><div class=\"card-top\"><div class=\"card-flag\">${FLAGS[c]||'🌐'}</div><div><div class=\"card-country\">${c}</div><div class=\"card-region\">${region}</div></div></div><div class=\"card-stats\"><div class=\"stat\"><div class=\"stat-label\">Latest (${s.latestYear||''})</div><div class=\"stat-val green\">${fmt(s.latest||0)}</div></div><div class=\"stat\"><div class=\"stat-label\">Average</div><div class=\"stat-val purple\">${fmt(Math.round(s.avg||0))}</div></div><div class=\"stat\"><div class=\"stat-label\">Peak</div><div class=\"stat-val orange\">${fmt(s.max||0)}</div></div><div class=\"stat\"><div class=\"stat-label\">Growth</div><div class=\"stat-val\">${badge(s.growth||0)}</div></div></div></div>`;}).join('');\n}\n\nfunction openDetail(c,from){\n  prevPage=from||'countries';\n  const s=SUMMARY[c]||{};\n  const pts=(WASTE_DATA[c]||[]).slice().sort((a,b)=>a.year-b.year);\n  document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));\n  document.querySelectorAll('.nav-btn').forEach(b=>b.classList.remove('active'));\n  document.getElementById('page-detail').classList.add('active');\n  document.getElementById('detailFlag').textContent=FLAGS[c]||'🌐';\n  document.getElementById('detailTitle').textContent=c;\n  document.getElementById('detailRegion').textContent=CONTINENTS[c]||'';\n  document.getElementById('detailStats').innerHTML=\n    `<div class=\"d-stat\"><div class=\"d-stat-label\">Latest (${s.latestYear})</div><div class=\"d-stat-val green\">${fmt(s.latest||0)}</div></div>`+\n    `<div class=\"d-stat\"><div class=\"d-stat-label\">Peak</div><div class=\"d-stat-val purple\">${fmt(s.max||0)}</div></div>`+\n    `<div class=\"d-stat\"><div class=\"d-stat-label\">Average</div><div class=\"d-stat-val orange\">${fmt(Math.round(s.avg||0))}</div></div>`+\n    `<div class=\"d-stat\"><div class=\"d-stat-label\">Growth</div><div class=\"d-stat-val\">${badge(s.growth||0)}</div></div>`+\n    `<div class=\"d-stat\"><div class=\"d-stat-label\">First Year</div><div class=\"d-stat-val\">${s.firstYear||''}</div></div>`+\n    `<div class=\"d-stat\"><div class=\"d-stat-label\">Records</div><div class=\"d-stat-val\">${s.count||0}</div></div>`;\n  if(activeChart) activeChart.destroy();\n  const ctx=document.getElementById('mainChart').getContext('2d');\n  const grad=ctx.createLinearGradient(0,0,0,370);\n  grad.addColorStop(0,'rgba(37,99,235,.25)');grad.addColorStop(1,'rgba(37,99,235,0)');\n  activeChart=new Chart(ctx,{type:'line',data:{datasets:[{label:'Recycling (tonnes)',data:pts.map(p=>({x:p.year,y:p.value})),borderColor:'#2563eb',backgroundColor:grad,borderWidth:2.5,pointBackgroundColor:'#2563eb',pointRadius:pts.length>30?2.5:5,pointHoverRadius:7,fill:true,tension:.35}]},options:{responsive:true,animation:{duration:750,easing:'easeInOutQuart'},plugins:{legend:{labels:{color:'#64748b'}},tooltip:{backgroundColor:'#ffffff',titleColor:'#1e293b',bodyColor:'#2563eb',borderColor:'#e2e8f0',borderWidth:1,callbacks:{title:i=>'Year: '+i[0].parsed.x,label:i=>' '+i[0].parsed.y.toLocaleString()+' tonnes'}}},scales:{x:{type:'linear',title:{display:true,text:'Year',color:'#64748b'},ticks:{color:'#64748b'},grid:{color:'rgba(226,232,240,.9)'}},y:{title:{display:true,text:'Recycling (tonnes)',color:'#64748b'},ticks:{color:'#64748b',callback:v=>fmt(v)},grid:{color:'rgba(226,232,240,.9)'}}}}}); \n  const maxV=Math.max(...pts.map(p=>p.value),1);\n  document.getElementById('yearTable').innerHTML='<thead><tr><th>Year</th><th>Recycling (tonnes)</th><th>Trend</th></tr></thead><tbody>'+[...pts].sort((a,b)=>b.year-a.year).map(p=>`<tr><td>${p.year}</td><td>${p.value.toLocaleString()}</td><td><div class=\"mini-bar\" style=\"width:${Math.round(p.value/maxV*230)}px\"></div></td></tr>`).join('')+'</tbody>';\n  window.scrollTo({top:0,behavior:'smooth'});\n}\n\nfunction goBack(){\n  document.getElementById('page-detail').classList.remove('active');\n  document.getElementById('page-'+prevPage).classList.add('active');\n  const idx={home:0,countries:1,rankings:2,trends:3};\n  if(idx[prevPage]!==undefined) document.querySelectorAll('.nav-btn')[idx[prevPage]].classList.add('active');\n  if(activeChart){activeChart.destroy();activeChart=null;}\n}\n\nfunction renderRankings(by){\n  let sorted=COUNTRIES.filter(c=>!c.startsWith('OECD')&&c!=='European Union (27 countries from 01/02/2020)');\n  if(by==='latest') sorted.sort((a,b)=>(SUMMARY[b]?.latest||0)-(SUMMARY[a]?.latest||0));\n  else if(by==='avg') sorted.sort((a,b)=>(SUMMARY[b]?.avg||0)-(SUMMARY[a]?.avg||0));\n  else if(by==='growth') sorted.sort((a,b)=>(SUMMARY[b]?.growth||0)-(SUMMARY[a]?.growth||0));\n  else sorted.sort((a,b)=>(SUMMARY[b]?.max||0)-(SUMMARY[a]?.max||0));\n  const key=by==='avg'?'avg':by==='growth'?'growth':by==='max'?'max':'latest';\n  const topV=SUMMARY[sorted[0]]?.[key]||1;\n  document.getElementById('rankList').innerHTML=sorted.slice(0,20).map((c,i)=>{\n    const s=SUMMARY[c]||{};const val=s[key]||0;\n    const nc=i===0?'gold':i===1?'silver':i===2?'bronze':'';\n    return `<div class=\"rank-item\" onclick=\"openDetail('${c.replace(/'/g,\"&#39;\")}','rankings')\"><div class=\"rank-num ${nc}\">#${i+1}</div><div class=\"rank-flag\">${FLAGS[c]||'🌐'}</div><div class=\"rank-name\">${c}</div><div class=\"rank-bar-wrap\"><div class=\"rank-bar\" style=\"width:${Math.round(val/topV*100)}%\"></div></div><div class=\"rank-val\">${by==='growth'?val.toFixed(1)+'%':fmt(Math.round(val))}</div></div>`;\n  }).join('');\n}\nfunction switchRank(by,btn){document.querySelectorAll('.rank-tab').forEach(b=>b.classList.remove('active'));btn.classList.add('active');renderRankings(by);}\n\nfunction initCompare(){renderCompareTags();renderCompareChart();filterCompare();}\nfunction filterCompare(){\n  const q=document.getElementById('compareSearch').value.toLowerCase();\n  const dd=document.getElementById('compareDropdown');\n  if(!q){dd.classList.remove('open');return;}\n  const m=COUNTRIES.filter(c=>c.toLowerCase().includes(q)&&!compareList.includes(c)).slice(0,8);\n  dd.innerHTML=m.map(c=>`<div class=\"c-opt\" onclick=\"addCompare('${c.replace(/'/g,\"&#39;\")}')\">${FLAGS[c]||'🌐'} ${c}</div>`).join('');\n  dd.classList.toggle('open',m.length>0);\n}\nfunction addCompare(c){if(compareList.length>=4||compareList.includes(c))return;compareList.push(c);document.getElementById('compareSearch').value='';document.getElementById('compareDropdown').classList.remove('open');renderCompareTags();renderCompareChart();}\nfunction removeCompare(c){const i=compareList.indexOf(c);if(i>-1)compareList.splice(i,1);renderCompareTags();renderCompareChart();}\nfunction renderCompareTags(){document.getElementById('compareTags').innerHTML=compareList.map(c=>`<div class=\"c-tag\">${FLAGS[c]||'🌐'} ${c} <span class=\"c-tag-remove\" onclick=\"removeCompare('${c.replace(/'/g,\"&#39;\")}')\">✕</span></div>`).join('');}\nfunction renderCompareChart(){\n  if(compareChartObj) compareChartObj.destroy();\n  if(!compareList.length) return;\n  const ctx=document.getElementById('compareChart').getContext('2d');\n  compareChartObj=new Chart(ctx,{type:'line',data:{datasets:compareList.map((c,i)=>({label:c,data:(WASTE_DATA[c]||[]).slice().sort((a,b)=>a.year-b.year).map(p=>({x:p.year,y:p.value})),borderColor:COLORS[i],backgroundColor:'transparent',borderWidth:2.5,pointRadius:3,pointHoverRadius:7,tension:.3}))},options:{responsive:true,animation:{duration:600},plugins:{legend:{labels:{color:'#64748b'}},tooltip:{mode:'index',intersect:false,backgroundColor:'#ffffff',titleColor:'#1e293b',borderColor:'#e2e8f0',borderWidth:1,callbacks:{title:i=>'Year: '+i[0].parsed.x,label:i=>' '+i[0].label+': '+i[0].parsed.y.toLocaleString()+' t'}}},scales:{x:{type:'linear',ticks:{color:'#64748b'},grid:{color:'rgba(226,232,240,.9)'}},y:{ticks:{color:'#64748b',callback:v=>fmt(v)},grid:{color:'rgba(226,232,240,.9)'}}}}}); \n}\ndocument.addEventListener('click',e=>{if(!e.target.closest('.compare-search-wrap'))document.getElementById('compareDropdown').classList.remove('open');});\ndocument.addEventListener('keydown',e=>{if(e.key==='Enter'&&document.getElementById('search')===document.activeElement)filterCards();});\nshowPage('home');\n\n</script>\n</body>\n</html>"

main :: IO ()
main = do
  putStrLn "\x1b[32m\xf0\x9f\x9a\x80  Waste Recycling Dashboard running at http://localhost:3000\x1b[0m"
  result <- loadWasteData
  case result of
    Left msg -> putStrLn $ "\x1b[33m\xe2\x84\xb9  " ++ msg ++ "\x1b[0m"
    Right ws -> putStrLn $ "\x1b[36m\xe2\x9c\x85  Loaded " ++ show (length ws)
                         ++ " records / " ++ show (length (uniqueCountries ws)) ++ " countries.\x1b[0m"
  scotty 3000 $ do
    get "/" $ html dashboardHtml
    get "/health" $ text "OK"
